// =============================================================================
// Cosmos DB Provider — EF Core 9 Breaking Change Fixes
// Apply these patterns in your separate Cosmos DB project.
// =============================================================================

#if false // Reference-only — not compiled in this project

using Microsoft.EntityFrameworkCore;

// ---------------------------------------------------------------------------
// BREAKING CHANGE 1: Discriminator property renamed from "Discriminator" to "$type"
// BREAKING CHANGE 2: id property no longer contains discriminator value
//
// Existing documents use "Discriminator" and compound ids like "Product|123".
// Configure the model to preserve backward compatibility.
// ---------------------------------------------------------------------------
class CosmosDbContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Keep using "Discriminator" so existing documents are still found.
        modelBuilder.Entity<Product>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Keep the old compound id format ("Product|123") so existing
        //         documents can still be looked up by id.
        modelBuilder.Entity<Product>().HasRootDiscriminatorInJsonId(true);
    }
}

class Product
{
    public int Id { get; set; }
    public string Name { get; set; } = "";
}

// ---------------------------------------------------------------------------
// BREAKING CHANGE 3: Sync I/O no longer supported on the Cosmos DB provider
//
// Synchronous methods (SaveChanges, ToList, First, Count, etc.) now throw.
// Convert all Cosmos queries and saves to their async equivalents.
// ---------------------------------------------------------------------------
class CosmosQueryService
{
    // ❌ BREAKS in EF Core 9 — throws InvalidOperationException
    // List<Product> GetAll(CosmosDbContext db) => db.Products.ToList();
    // void Save(CosmosDbContext db) => db.SaveChanges();
    // var p = db.Products.First();

    // ✅ Fix — use async equivalents
    async Task<List<Product>> GetAllAsync(CosmosDbContext db)
        => await db.Products.ToListAsync();

    async Task SaveAsync(CosmosDbContext db)
        => await db.SaveChangesAsync();

    async Task<Product> GetFirstAsync(CosmosDbContext db)
        => await db.Products.FirstAsync();
}

#endif

